import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from "node:fs";
import { relative, resolve, sep } from "node:path";
import type { Plugin, ResolvedConfig } from "vite";

/** Static output a change to which must invalidate the app shell cache. */
const PRECACHE_EXTENSIONS = new Set([
  ".html",
  ".webmanifest",
  ".svg",
  ".png",
  ".jpg",
  ".jpeg",
  ".webp",
  ".ico",
  ".json",
  ".js",
  ".css",
  ".woff",
  ".woff2"
]);

/** Generated by this plugin, not part of the shell; `_headers` is a host directive, maps are debug data. */
function isExcluded(relativePath: string): boolean {
  const name = relativePath.split("/").pop() || relativePath;
  return name === "sw.js" || name === "_headers" || relativePath.endsWith(".map");
}

function hasCachableExtension(relativePath: string): boolean {
  const dot = relativePath.lastIndexOf(".");
  if (dot < 0) return false;
  return PRECACHE_EXTENSIONS.has(relativePath.slice(dot).toLowerCase());
}

function collectFiles(directory: string, root: string, files: string[] = []): string[] {
  for (const entry of readdirSync(directory, { withFileTypes: true })) {
    const absolute = resolve(directory, entry.name);
    if (entry.isDirectory()) {
      collectFiles(absolute, root, files);
      continue;
    }
    if (!entry.isFile()) continue;
    const relativePath = relative(root, absolute).split(sep).join("/");
    if (isExcluded(relativePath) || !hasCachableExtension(relativePath)) continue;
    files.push(relativePath);
  }
  return files.sort();
}

function buildHash(outDir: string, files: string[]): string {
  const hash = createHash("sha256");
  for (const file of files) {
    hash.update(file);
    hash.update("\0");
    hash.update(readFileSync(resolve(outDir, file)));
    hash.update("\0");
  }
  return hash.digest("hex").slice(0, 12);
}

function buildServiceWorker(cacheName: string, precache: string[]): string {
  return `/*
 * Jantt app shell service worker. Generated by vite-pwa-plugin.ts; do not edit dist/sw.js.
 *
 * Policy: same-origin GET only. Firebase, GitHub, AI providers, local Ollama, remote imports and
 * every non-GET request pass straight through untouched. Navigations are network-first with an
 * offline shell fallback, hashed build assets are cache-first, other shell files revalidate in
 * the background.
 */
const CACHE_NAME = ${JSON.stringify(cacheName)};
const PRECACHE = ${JSON.stringify(["./", ...precache.map((file) => `./${file}`)], null, 2)};
const SHELL_INDEX = "./index.html";
const IMMUTABLE_ASSET = /\\/assets\\/.*-[A-Za-z0-9_-]{6,}\\.(js|css|woff2?)$/i;

function shouldBypassServiceWorker(requestUrl, method, swOrigin) {
  if (method.toUpperCase() !== "GET") return true;
  var url;
  try {
    url = new URL(requestUrl, swOrigin);
  } catch (error) {
    return true;
  }
  if (url.protocol !== "http:" && url.protocol !== "https:") return true;
  if (url.origin !== swOrigin) return true;
  if (url.pathname.endsWith("/sw.js")) return true;
  return false;
}

self.addEventListener("install", function (event) {
  event.waitUntil(
    (async function () {
      var cache = await caches.open(CACHE_NAME);
      await Promise.all(
        PRECACHE.map(function (url) {
          return cache.add(url).catch(function () {
            return undefined;
          });
        })
      );
      if (!self.registration.active) await self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", function (event) {
  event.waitUntil(
    (async function () {
      var cacheNames = await caches.keys();
      await Promise.all(
        cacheNames.map(function (name) {
          if (name.indexOf("jantt-shell-") === 0 && name !== CACHE_NAME) return caches.delete(name);
          return undefined;
        })
      );
      await self.clients.claim();
    })()
  );
});

self.addEventListener("message", function (event) {
  if (event.data && event.data.type === "SKIP_WAITING") self.skipWaiting();
});

self.addEventListener("fetch", function (event) {
  var request = event.request;
  if (shouldBypassServiceWorker(request.url, request.method, self.location.origin)) return;
  event.respondWith(handleRequest(event, request));
});

async function handleRequest(event, request) {
  var url = new URL(request.url);
  var cache = await caches.open(CACHE_NAME);

  if (request.mode === "navigate") {
    var isShellNavigation = !url.pathname.endsWith(".html") || url.pathname.endsWith("/index.html");
    try {
      var network = await fetch(request);
      if (network && network.ok) {
        if (isShellNavigation) await cache.put(SHELL_INDEX, network.clone());
        else await cache.put(request, network.clone());
      }
      return network;
    } catch (error) {
      if (isShellNavigation) {
        var shell = await cache.match(SHELL_INDEX);
        return shell || Response.error();
      }
      var page = await cache.match(request);
      return page || Response.error();
    }
  }

  if (IMMUTABLE_ASSET.test(url.pathname)) {
    var cachedAsset = await cache.match(request);
    if (cachedAsset) return cachedAsset;
    try {
      var assetResponse = await fetch(request);
      if (assetResponse && assetResponse.ok) await cache.put(request, assetResponse.clone());
      return assetResponse;
    } catch (error) {
      return Response.error();
    }
  }

  var cached = await cache.match(request);
  var refresh = fetch(request).then(function (response) {
    if (!response || !response.ok) return response;
    return cache.put(request, response.clone()).then(function () {
      return response;
    });
  });

  if (cached) {
    event.waitUntil(
      refresh.catch(function () {
        return undefined;
      })
    );
    return cached;
  }

  try {
    return await refresh;
  } catch (error) {
    return Response.error();
  }
}
`;
}

/**
 * Zero-dependency Vite plugin that emits a deterministic offline app-shell service worker after
 * every production build. The cache name is derived from the emitted shell files, so a deploy
 * that changes any asset installs a fresh cache and never serves stale HTML.
 */
export function janttPwaPlugin(): Plugin {
  let resolvedConfig: ResolvedConfig | null = null;

  return {
    name: "jantt-pwa",
    apply: "build",
    configResolved(config) {
      resolvedConfig = config;
    },
    async closeBundle() {
      if (!resolvedConfig) return;
      const outDir = resolve(resolvedConfig.root, resolvedConfig.build.outDir);
      if (!existsSync(outDir) || !statSync(outDir).isDirectory()) return;

      const files = collectFiles(outDir, outDir);
      if (files.length === 0) return;

      const cacheName = `jantt-shell-${buildHash(outDir, files)}`;
      writeFileSync(resolve(outDir, "sw.js"), buildServiceWorker(cacheName, files), "utf8");
      resolvedConfig.logger.info(
        `jantt-pwa: ${cacheName} with ${files.length} shell files`,
        { timestamp: true }
      );
    }
  };
}
